input.content:
import { unstable_cache, revalidateTag } from 'next/cache';
import { getAllProducts } from '@/lib/db';

const getCachedProducts = unstable_cache(
  async () => getAllProducts(),
  ['products-cache'],
  { tags: ['products'] }
);

export default async function Page() {
  const products = await getCachedProducts();

  async function syncCatalog() {
    'use server';

    // Simulate a background job that syncs data, then invalidates the cache
    setTimeout(async () => {
      // This might fail if revalidateTag needs to be inside the request context
      try {
        revalidateTag('products');
        console.log("Revalidated tag successfully");
      } catch (err) {
        console.error("Failed to revalidate:", err);
      }
    }, 100);
  }

  return (
    <div>
      <form action={syncCatalog}>
        <button type="submit">Sync latest catalog</button>
      </form>
      <ul>
        {products.map((p: any) => (
          <li key={p.id}>{p.name} - ${p.price}</li>
        ))}
      </ul>
    </div>
  );
}
